"""Reject scheduler evidence that loses numerical identity, coverage or heap gates."""
import copy
import importlib.util
import json
from pathlib import Path
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("schedule_benchmark", ROOT / "Tools/Scheduling/benchmark.py")
benchmark = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(benchmark)
MATRIX = [{"name": "light"}, {"name": "full"}, {"name": "selected"}, {"name": "whole"}]


def capture(mode):
    names = [f"Schedule.{operation}.{row['name']}" for row in MATRIX for operation in benchmark.OPERATIONS]
    if mode == "allocation": names.append(benchmark.CONTROL)
    metrics = ["wallClock", "cpuTotal"] if mode == "timing" else ["wallClock", *benchmark.DIAGNOSTICS]
    rows = []
    for name in names:
        allocating = name == benchmark.CONTROL or ".Prepare." in name
        measurements = []
        for metric in metrics:
            maximum = 1 if allocating or metric in ("wallClock", "cpuTotal") else 0
            measurements.append(dict(metric={metric: {}}, scalingFactor=1,
                statistics=dict(histogram=dict(_totalCount=10, maxValue=maximum, counts=[10]))))
        rows.extend([dict(name=name, target="ScheduleBenchmarks"), measurements])
    return dict(results=rows)


class ScheduleBenchmarkTests(unittest.TestCase):
    def test_expected_matrix_has_each_composition_precision_rate_and_boundary(self):
        cases = list(benchmark.expected_cases().values())
        self.assertEqual(len(cases), 20)
        primary = [row for row in cases if row["kind"] == "preview" and row["channels"] == 1]
        self.assertEqual({(row["precision"], row["rate"], row["composition"]) for row in primary},
            {(precision, rate, composition) for precision in ("float32", "float64")
             for rate in (16000, 44100, 48000) for composition in ("light", "full")})
        self.assertEqual({(row["precision"], row["layout"]) for row in cases if row["channels"] == 2},
            {(precision, layout) for precision in ("float32", "float64") for layout in ("interleaved", "planar")})
        self.assertEqual(sum(row["kind"] == "selected" for row in cases), 2)
        self.assertEqual(sum(row["kind"] == "whole" for row in cases), 2)

    def test_heap_maxima_and_every_positive_control_are_required(self):
        good = capture("allocation")
        self.assertEqual(len(benchmark.validate_raw(good, MATRIX, "allocation")), 9)
        for metric in benchmark.DIAGNOSTICS:
            bad = copy.deepcopy(good)
            for measurement in bad["results"][-1]:
                if metric in measurement["metric"]: measurement["statistics"]["histogram"]["maxValue"] = 0
            with self.assertRaisesRegex(ValueError, "Unavailable"):
                benchmark.validate_raw(bad, MATRIX, "allocation")
        for index in range(len(MATRIX)):
            for metric in benchmark.ALLOCATIONS:
                bad = copy.deepcopy(good)
                for measurement in bad["results"][index * 4 + 3]:
                    if metric in measurement["metric"]: measurement["statistics"]["histogram"]["maxValue"] = 1
                with self.assertRaisesRegex(ValueError, "Steady-state"):
                    benchmark.validate_raw(bad, MATRIX, "allocation")

    def test_raw_distributions_reject_missing_duplicate_under_sampled_or_negative_data(self):
        for mode in ("timing", "allocation"):
            good = capture(mode)
            benchmark.validate_raw(good, MATRIX, mode)
            changes = [lambda r: r["results"].pop(),
                lambda r: r["results"].__setitem__(2, r["results"][0]),
                lambda r: r["results"][0].__setitem__("target", "Wrong"),
                lambda r: r["results"][1].pop(),
                lambda r: r["results"][1][0].__setitem__("scalingFactor", 100),
                lambda r: r["results"][1][0]["statistics"]["histogram"].__setitem__("_totalCount", 9),
                lambda r: r["results"][1][0]["statistics"]["histogram"].__setitem__("counts", [-1, 11]),
                lambda r: r["results"][1][0]["statistics"]["histogram"].__setitem__("maxValue", 0)]
            for change in changes:
                bad = copy.deepcopy(good); change(bad)
                with self.assertRaises(ValueError): benchmark.validate_raw(bad, MATRIX, mode)

    def test_export_requires_complete_metrics_and_units(self):
        rows = [dict(name=f"case - {metric}", value=3, unit="ns")
                for metric in ("Time (wall clock)", "Time (total CPU)")]
        benchmark.validate_export(rows, ["case"], "timing")
        for bad in (rows[:1], rows + rows, [{**rows[0], "unit": "ms"}, rows[1]],
                    [{**rows[0], "value": float("nan")}, rows[1]]):
            with self.assertRaises(ValueError): benchmark.validate_export(bad, ["case"], "timing")

    def test_native_receipts_reject_changed_recipe_support_population_and_reference(self):
        examples = json.loads(CAPTURED)
        expected = {row["name"]: benchmark.expected_cases()[row["name"]] for row in examples}
        with patch.object(benchmark.workloads, "expected_cases", return_value=expected):
            benchmark.validate_matrix(examples)
            changes = [lambda r: r.pop(), lambda r: r.append(r[0]),
                lambda r: r[0]["workload"].__setitem__("sourceTileCapacity", 128),
                lambda r: r[0]["workload"]["profile"].__setitem__("channelConversion", "implicitMean"),
                lambda r: r[0]["workload"]["profile"]["levels"].__setitem__("windowLength", 401),
                lambda r: r[0]["workload"]["profile"]["pitch"]["estimator"].__setitem__("threshold", .2),
                lambda r: r[0]["workload"]["profile"].__setitem__("schemaVersion", True),
                lambda r: r[0]["workload"]["identity"].__setitem__("sha256", "0" * 64),
                lambda r: r[0].__setitem__("preparedInputBytes", 0),
                lambda r: r[0].__setitem__("preparedBufferBytes", 0),
                lambda r: r[0].__setitem__("analyzedDurationSeconds", True),
                lambda r: r[0].__setitem__("inputSHA256", "unknown"),
                lambda r: r[0]["directDigest"]["levels"].__setitem__("checksum", 0),
                lambda r: r[0]["splitDigest"]["levels"].__setitem__("frames", 0)]
            for change in changes:
                bad = copy.deepcopy(examples); change(bad)
                with self.assertRaises(ValueError): benchmark.validate_matrix(bad)
            for lane in ("levels", "pitch", "cpps"):
                bad = copy.deepcopy(examples)
                for key in ("digest", "directDigest", "splitDigest"):
                    bad[1][key][lane]["frames"] += 1
                with self.assertRaises(ValueError): benchmark.validate_matrix(bad)
            bad = copy.deepcopy(examples)
            weighted = next(row for row in bad if row["workload"]["composition"] == "full")
            weighted["workload"]["profile"]["levels"]["kWeighting"]["shelf"]["b0"] += .01
            with self.assertRaisesRegex(ValueError, "coefficients"): benchmark.validate_matrix(bad)
            bad = copy.deepcopy(examples)
            selected = next(row for row in bad if row["workload"]["kind"] == "selected")
            selected["workload"]["maskPlan"]["observations"][0]["source"]["sampleCount"] += 1
            with self.assertRaises(ValueError): benchmark.validate_matrix(bad)


